(4870150, 705270, 85936, '<td valign="top">Bad choice of border for an evening shot.</td>', 'Bad choice of border for an evening shot.', '2008-08-06 12:43:28.000000', NULL, 1),
(4870161, 706774, 94718, '<td valign="top">Hi! sorry to tell you but this is a very average image! I mean - in my opinion - if you wanna take a good image of a fire, you should go to its level , those are the great pics! apart from the point of view it''s not even sharp, and you should have had a longer exposure time I think! But this is only my opinion, the topic worth trying again!!! All the best</td>', 'Hi! sorry to tell you but this is a very average image! I mean - in my opinion - if you wanna take a good image of a fire, you should go to its level , those are the great pics! apart from the point of view it''s not even sharp, and you should have had a longer exposure time I think! But this is only my opinion, the topic worth trying again!!! All the best', '2008-08-06 12:47:31.000000', NULL, 1),
(4870163, 705820, 85936, '<td valign="top">I really like this image. It reminds me of being little.. great job!</td>', 'I really like this image. It reminds me of being little.. great job!', '2008-08-06 12:47:45.000000', NULL, 1),
