(4870201, 706425, 85388, '<td valign="top">You should''ve really used a straightening tool to fix that horizon. Picasa is a good free piece of software that can do that, and more.</td>', 'You should''ve really used a straightening tool to fix that horizon. Picasa is a good free piece of software that can do that, and more.', '2008-08-06 12:56:59.000000', NULL, 1),
(4870208, 706734, 85388, '<td valign="top">I love the effect of the road leading you down the hill, and then up into the very moody sky.</td>', 'I love the effect of the road leading you down the hill, and then up into the very moody sky.', '2008-08-06 12:57:43.000000', NULL, 1),
(4870211, 707136, 85388, '<td valign="top">I wanted to do the exact same thing, but had a hard time finding a farm</td>', 'I wanted to do the exact same thing, but had a hard time finding a farm', '2008-08-06 12:58:56.000000', NULL, 1),
(4870215, 706821, 85388, '<td valign="top">Excellent capture!</td>', 'Excellent capture!', '2008-08-06 13:00:32.000000', NULL, 1),
(4870229, 707228, 3087, '<td valign="top">A bit cliched (which is not necessarily a bad thing) but a nice clean silhouette of the couple with a very striking sky an sea behind.</td>', 'A bit cliched (which is not necessarily a bad thing) but a nice clean silhouette of the couple with a very striking sky an sea behind.', '2008-08-06 13:04:42.000000', NULL, 1),
(4870232, 705637, 3087, '<td valign="top">Lovely muted colours with a nice sheen on the dragonfly tail. I like how the greens and blues of the dragonfly contrast with the mainly orange background. Lovely composition too.</td>', 'Lovely muted colours with a nice sheen on the dragonfly tail. I like how the greens and blues of the dragonfly contrast with the mainly orange background. Lovely composition too.', '2008-08-06 13:05:31.000000', NULL, 1),
(4870233, 707149, 3087, '<td valign="top">Strong composition. The colour tone seems a touch too turquoise to be realistic but it''s pretty nonetheless.</td>', 'Strong composition. The colour tone seems a touch too turquoise to be realistic but it''s pretty nonetheless.', '2008-08-06 13:06:16.000000', NULL, 1),
(4870234, 706570, 3087, '<td valign="top">I like this idea very much though I think I''d like it more if there were one of those trees or bushes nice and clear (and free of dancers infront) to contrast with it''s sharpness with the motion-blurred dancers.</td>', 'I like this idea very much though I think I''d like it more if there were one of those trees or bushes nice and clear (and free of dancers infront) to contrast with it''s sharpness with the motion-blurred dancers.', '2008-08-06 13:07:03.000000', NULL, 1),
(4870236, 707167, 3087, '<td valign="top">Lovely light and I like the whimsical "tree-with-four-trunks" that is the main subject.</td>', 'Lovely light and I like the whimsical "tree-with-four-trunks" that is the main subject.', '2008-08-06 13:07:43.000000', NULL, 1),
(4870237, 706922, 3087, '<td valign="top">Lovely lighting, nice simple composition - the inclusion of lots of sky and those long rays of sunlight is great.</td>', 'Lovely lighting, nice simple composition - the inclusion of lots of sky and those long rays of sunlight is great.', '2008-08-06 13:08:12.000000', NULL, 1),
(4870240, 707014, 3087, '<td valign="top">Pretty and I like the unusual centred composition.</td>', 'Pretty and I like the unusual centred composition.', '2008-08-06 13:08:53.000000', NULL, 1),
(4870241, 707080, 3087, '<td valign="top">A nice idea but, for my tastes, the colours are pumped up much too far beyond realistic.</td>', 'A nice idea but, for my tastes, the colours are pumped up much too far beyond realistic.', '2008-08-06 13:09:32.000000', NULL, 1),
(4870303, 707443, 29777, '<td valign="top">nice image, but it does not make me think "evening". sorry</td>', 'nice image, but it does not make me think "evening". sorry', '2008-08-06 13:50:14.000000', NULL, 1),
(4870307, 707254, 29777, '<td valign="top">The animals are too dark. A lower POV may have given better silhouette.</td>', 'The animals are too dark. A lower POV may have given better silhouette.', '2008-08-06 13:51:49.000000', NULL, 1),
(4870315, 707149, 29777, '<td valign="top">very nice.</td>', 'very nice.', '2008-08-06 13:53:43.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(4870317, 706403, 29777, '<td valign="top">seems more stormy than evening. A bit more contrast would add impact. difficult to isolate a single subject.</td>', 'seems more stormy than evening. A bit more contrast would add impact. difficult to isolate a single subject.', '2008-08-06 13:55:29.000000', NULL, 1),
(4870318, 705742, 29777, '<td valign="top">great color.</td>', 'great color.', '2008-08-06 13:56:06.000000', NULL, 1),
(4870340, 706336, 83313, '<td valign="top">A very calm and relaxing image. I like that you kept the sky relatively subdued and did not crank up the saturation to unnatural levels.</td>', 'A very calm and relaxing image. I like that you kept the sky relatively subdued and did not crank up the saturation to unnatural levels.', '2008-08-06 14:03:57.000000', NULL, 1),
(4870350, 707406, 83313, '<td valign="top">There must be a story to this that relates to your title. What are those things on the side of the board? I like the comp and subject, though the wood parts seem a bit pixelated and odd looking, as if they scaled down in an unexpected way.</td>', 'There must be a story to this that relates to your title. What are those things on the side of the board? I like the comp and subject, though the wood parts seem a bit pixelated and odd looking, as if they scaled down in an unexpected way.', '2008-08-06 14:07:17.000000', NULL, 1),
(4870355, 706629, 83313, '<td valign="top">Nice. I have trouble getting backlit shots to look good, so I really appreciate something like this.</td>', 'Nice. I have trouble getting backlit shots to look good, so I really appreciate something like this.', '2008-08-06 14:08:52.000000', NULL, 1),
(4870357, 707473, 83313, '<td valign="top">Just needs a few minor repairs, I''ll get the nail gun.</td>', 'Just needs a few minor repairs, I''ll get the nail gun.', '2008-08-06 14:09:48.000000', NULL, 1),
(4870360, 707080, 83313, '<td valign="top">Nice, though I find the strong orange sky a little TOO strong. You caught a wonderful curve in those clouds.</td>', 'Nice, though I find the strong orange sky a little TOO strong. You caught a wonderful curve in those clouds.', '2008-08-06 14:11:02.000000', NULL, 1),
(4870367, 705774, 83313, '<td valign="top">A lot of visual interes here. I like the way the tree leaves conforms to the shape of the trunk on the other side of the frame. It''s as if they are parting to give me a view.</td>', 'A lot of visual interes here. I like the way the tree leaves conforms to the shape of the trunk on the other side of the frame. It''s as if they are parting to give me a view.', '2008-08-06 14:12:51.000000', NULL, 1),
(4870377, 705820, 83313, '<td valign="top">A nice and pleasant scene, though the pier in the corner tends to draw my eye away from the children exploring. If there were not any editing rules for the cahllenge, cloning it out would really improve the scene.</td>', 'A nice and pleasant scene, though the pier in the corner tends to draw my eye away from the children exploring. If there were not any editing rules for the cahllenge, cloning it out would really improve the scene.', '2008-08-06 14:15:22.000000', NULL, 1),
(4870380, 707180, 83313, '<td valign="top">An interesting view. The horizon line looks a little oversharp.</td>', 'An interesting view. The horizon line looks a little oversharp.', '2008-08-06 14:16:35.000000', NULL, 1),
(4870383, 707370, 83313, '<td valign="top">I won''t give you any kudos for creative titles, but I really like the scene here. Is this a drydock for a boat?</td>', 'I won''t give you any kudos for creative titles, but I really like the scene here. Is this a drydock for a boat?', '2008-08-06 14:17:55.000000', NULL, 1),
(4870388, 707139, 83313, '<td valign="top">A really good and dynamic scene, but it seems a little unrealistically saturated to me. A result of bringing the detail out of a low light scene, I am certain. I suspect my feedback in  that regard will be in the minority!</td>', 'A really good and dynamic scene, but it seems a little unrealistically saturated to me. A result of bringing the detail out of a low light scene, I am certain. I suspect my feedback in  that regard will be in the minority!', '2008-08-06 14:20:39.000000', NULL, 1),
