(4871486, 707255, 56275, '<td valign="top">I really like the scene you captured here. The lens flare adds to the shot.</td>', 'I really like the scene you captured here. The lens flare adds to the shot.', '2008-08-06 21:59:18.000000', NULL, 1),
(4871490, 707441, 56275, '<td valign="top">I love that you captured the birds in this shot. Really draws your eyes to a good focal point.. However, the photo is pretty out of focus, and seems over-sharpened to me.</td>', 'I love that you captured the birds in this shot. Really draws your eyes to a good focal point.. However, the photo is pretty out of focus, and seems over-sharpened to me.', '2008-08-06 22:02:44.000000', NULL, 1),
