(4872095, 707239, 66108, '<td valign="top">Hello!<br/> <br/>I think feeling of this photo is very good, but if you ask me, I would put the girl to the left side, and try the portrait style, not the landscape. Maybe girl could be a little bit closer. Well, nice shot!<br/> <br/>Have nice day!</td>', 'Hello! I think feeling of this photo is very good, but if you ask me, I would put the girl to the left side, and try the portrait style, not the landscape. Maybe girl could be a little bit closer. Well, nice shot! Have nice day!', '2008-08-07 04:52:53.000000', NULL, 1),
(4872173, 707457, 67152, '<td valign="top">it is too bad you are only able to show us 640 pixels - this is a nice cityscape</td>', 'it is too bad you are only able to show us 640 pixels - this is a nice cityscape', '2008-08-07 07:16:15.000000', NULL, 1),
(4872176, 707350, 67152, '<td valign="top">gorgeous tones and glistening cobblestones - love the forgotten people in the far right</td>', 'gorgeous tones and glistening cobblestones - love the forgotten people in the far right', '2008-08-07 07:17:50.000000', NULL, 1),
(4872177, 706553, 67152, '<td valign="top">pretty colors and cool landmark - but the shadowed area on the right to obscure our view doesn''t work for me</td>', 'pretty colors and cool landmark - but the shadowed area on the right to obscure our view doesn''t work for me', '2008-08-07 07:18:23.000000', NULL, 1),
(4872178, 707177, 67152, '<td valign="top">the soft light, the missing people, the pastel hues - very nice stuff</td>', 'the soft light, the missing people, the pastel hues - very nice stuff', '2008-08-07 07:18:55.000000', NULL, 1),
(4872180, 706489, 67152, '<td valign="top">i love how the light is licking the tops of the mountains - but i don''t think narrow crop and the  sky (oversaturated reds and oversmoothed) work here</td>', 'i love how the light is licking the tops of the mountains - but i don''t think narrow crop and the  sky (oversaturated reds and oversmoothed) work here', '2008-08-07 07:20:19.000000', NULL, 1),
(4872181, 706403, 67152, '<td valign="top">lovely image - the richness of the sky tones, the details in the roof - the end of days for both the barn and the sunflowers...nice stuff</td>', 'lovely image - the richness of the sky tones, the details in the roof - the end of days for both the barn and the sunflowers...nice stuff', '2008-08-07 07:21:13.000000', NULL, 1),
(4872183, 707014, 67152, '<td valign="top">wow!  i love these type of images where the hills create the depth of the image - a very graphic like feel while being very real at the same time</td>', 'wow!  i love these type of images where the hills create the depth of the image - a very graphic like feel while being very real at the same time', '2008-08-07 07:22:08.000000', NULL, 1),
(4872185, 706768, 67152, '<td valign="top">gorgeous sky - i wonder if a bit less fill flash would have made this a bit more natural a feel</td>', 'gorgeous sky - i wonder if a bit less fill flash would have made this a bit more natural a feel', '2008-08-07 07:22:54.000000', NULL, 1),
(4872186, 705685, 67152, '<td valign="top">eery image - the sky and ground almost seem like from two separate iamges - neat effect</td>', 'eery image - the sky and ground almost seem like from two separate iamges - neat effect', '2008-08-07 07:23:41.000000', NULL, 1),
(4872187, 705825, 67152, '<td valign="top">nice work to bring out the haze to emphasize the rays in the sky</td>', 'nice work to bring out the haze to emphasize the rays in the sky', '2008-08-07 07:24:54.000000', NULL, 1),
(4872188, 706747, 67152, '<td valign="top">lovely sceene - the barn, the light on the grass - it''s all good stuff<br/> <br/>i just see a lot of layers of pixelation in the sky which cost this one some points - a bit of smoothing really would have helped here</td>', 'lovely sceene - the barn, the light on the grass - it''s all good stuff i just see a lot of layers of pixelation in the sky which cost this one some points - a bit of smoothing really would have helped here', '2008-08-07 07:26:10.000000', NULL, 1),
(4872190, 707233, 67152, '<td valign="top">really good composition - the repeating shapes and placement of the waterfalls work really well</td>', 'really good composition - the repeating shapes and placement of the waterfalls work really well', '2008-08-07 07:28:09.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(4872197, 707255, 67152, '<td valign="top">lovely quiet scene - i can almost hear the water flowing - i just wonder about the choice to super-saturate it - the bottom left corner really seem overdone</td>', 'lovely quiet scene - i can almost hear the water flowing - i just wonder about the choice to super-saturate it - the bottom left corner really seem overdone', '2008-08-07 07:31:28.000000', NULL, 1),
(4872198, 706405, 67152, '<td valign="top">city scenes in the evening are always cool and this one has potential - i am just not convinced by the choice of perspective - the streets draw us in a straight line into the image - a choice to draw us in at a diagonal would have brought more interest IMO</td>', 'city scenes in the evening are always cool and this one has potential - i am just not convinced by the choice of perspective - the streets draw us in a straight line into the image - a choice to draw us in at a diagonal would have brought more interest IMO', '2008-08-07 07:32:58.000000', NULL, 1),
(4872200, 707178, 67152, '<td valign="top">love the choice of dark here - the detail is all there for us to view if we are willing to stop - the mountains, the boat, the shore, the house on the other side - nice, nice, nice</td>', 'love the choice of dark here - the detail is all there for us to view if we are willing to stop - the mountains, the boat, the shore, the house on the other side - nice, nice, nice', '2008-08-07 07:34:38.000000', NULL, 1),
(4872218, 706658, 67152, '<td valign="top">the boat, the shore, the blues all work really well - but i am not convinced of the crop or the choice of wide angle</td>', 'the boat, the shore, the blues all work really well - but i am not convinced of the crop or the choice of wide angle', '2008-08-07 07:41:01.000000', NULL, 1),
(4872249, 706952, 67152, '<td valign="top">excellent vision to use the good light here - it amazes me how so many photogs have to shoot into the sun at sunset when the best images are usually behind them</td>', 'excellent vision to use the good light here - it amazes me how so many photogs have to shoot into the sun at sunset when the best images are usually behind them', '2008-08-07 08:56:11.000000', NULL, 1),
