(4877096, 706768, 14867, '<td valign="top">Very well done, excellent technique, but it''s nicely composed as well.</td>', 'Very well done, excellent technique, but it''s nicely composed as well.', '2008-08-09 12:57:07.000000', NULL, 1),
(4877099, 707169, 14867, '<td valign="top">Slighly overexposed. The sun is indeed low, but the image don''t convey an evening mood IMO.<br/>The composition is well balanced</td>', 'Slighly overexposed. The sun is indeed low, but the image don''t convey an evening mood IMO.The composition is well balanced', '2008-08-09 13:00:47.000000', NULL, 1),
(4877100, 707394, 14867, '<td valign="top">Beautiful sky, spoiled by a not particularly attractive foreground</td>', 'Beautiful sky, spoiled by a not particularly attractive foreground', '2008-08-09 13:01:31.000000', NULL, 1),
(4877103, 707371, 14867, '<td valign="top">Creative and rather fascinating.<br/>Im curious to know how you realized that.<br/>A pity the sky is very noisy</td>', 'Creative and rather fascinating.Im curious to know how you realized that.A pity the sky is very noisy', '2008-08-09 13:04:01.000000', NULL, 1),
