(4884317, 707149, 33352, '<td valign="top">Very good finish, congratulations on the ribbon</td>', 'Very good finish, congratulations on the ribbon', '2008-08-13 01:04:42.000000', NULL, 0),
(4884324, 707315, 32872, '<td valign="top">Congratulations on getting a blue ribbon for such a gorgeous image!  I''ve already gushed over its astounding beauty!</td>', 'Congratulations on getting a blue ribbon for such a gorgeous image!  I''ve already gushed over its astounding beauty!', '2008-08-13 01:06:01.000000', NULL, 0),
(4884329, 707315, 87158, '<td valign="top">I love Mt. Hood and you framed it beautifully.  From Timothy Lake?  I really like the light, the reflection and the clarity of all your details from close to far.  Would be very interested in knowing what you did to make this pop.  Congratulations!</td>', 'I love Mt. Hood and you framed it beautifully.  From Timothy Lake?  I really like the light, the reflection and the clarity of all your details from close to far.  Would be very interested in knowing what you did to make this pop.  Congratulations!', '2008-08-13 01:07:08.000000', NULL, 0),
(4884360, 707381, 82749, '<td valign="top">Very interesting patterns and shapes, nice rich color as well.</td>', 'Very interesting patterns and shapes, nice rich color as well.', '2008-08-13 01:12:11.000000', NULL, 0),
(4884382, 707315, 82749, '<td valign="top">Congrats on the blue, wonderful reflection, very beautiful.</td>', 'Congrats on the blue, wonderful reflection, very beautiful.', '2008-08-13 01:14:20.000000', NULL, 0),
(4884400, 707315, 28359, '<td valign="top">Awesome shot of Mt Hood...Congrats!</td>', 'Awesome shot of Mt Hood...Congrats!', '2008-08-13 01:16:58.000000', NULL, 0),
(4884405, 707350, 88822, '<td valign="top">I thought this would score higher, but never the less, it''s a nice finish.  Congrats.</td>', 'I thought this would score higher, but never the less, it''s a nice finish.  Congrats.', '2008-08-13 01:18:17.000000', NULL, 0),
(4884408, 706734, 22301, '<td valign="top">Congrats on back to back to back personal best scores! I thought this was great. The clouds are wonderful. Congrats on the score again. :)</td>', 'Congrats on back to back to back personal best scores! I thought this was great. The clouds are wonderful. Congrats on the score again. :)', '2008-08-13 01:18:36.000000', NULL, 0),
