(4884424, 707381, 88822, '<td valign="top">Very nice shot.  Still in the 30''s.</td>', 'Very nice shot.  Still in the 30''s.', '2008-08-13 01:21:24.000000', NULL, 0),
(4884431, 707409, 22301, '<td valign="top">I thought it was great, sorry you didn''t get a better score. Its heard to find unique ways to shoot the moon and think you succeeded.</td>', 'I thought it was great, sorry you didn''t get a better score. Its heard to find unique ways to shoot the moon and think you succeeded.', '2008-08-13 01:22:49.000000', NULL, 0),
(4884439, 707315, 59267, '<td valign="top"><table align="center" width="95%"><tr><td><div class="textsm"><b>Originally posted by wizardry:</b></div><hr/><i> 3 second shutter? Are you using a ND filter here? Nice job with this amazing image! </i></td></tr></table> <br/>Yes I did.</td>', 'Originally posted by wizardry: 3 second shutter? Are you using a ND filter here? Nice job with this amazing image!  Yes I did.', '2008-08-13 01:24:10.000000', NULL, 0),
(4884447, 707126, 80096, '<td valign="top">Thank you all for the wonderful comments! This was indeed a special image for me in that it was not planned in fact, my original intent was to capture some images of the moon. But the moon never appeared so I ended up capturing images of the stars instead. But most exciting of all was the fireball that sailed overhead while I was there. At first, I thought it was stray fireworks but the next day there was an article in the local paper about the meteorite sitings in the area. I think this was a very lucky night for me, my first ribbon entry and my first meteorite siting!</td>', 'Thank you all for the wonderful comments! This was indeed a special image for me in that it was not planned in fact, my original intent was to capture some images of the moon. But the moon never appeared so I ended up capturing images of the stars instead. But most exciting of all was the fireball that sailed overhead while I was there. At first, I thought it was stray fireworks but the next day there was an article in the local paper about the meteorite sitings in the area. I think this was a very lucky night for me, my first ribbon entry and my first meteorite siting!', '2008-08-13 01:25:09.000000', NULL, 0),
(4884464, 707126, 60862, '<td valign="top">Oh, that is spectacular!  I just love the change in the sky from ground up and the stars.  Congrats on your first ribbon and new personal best!</td>', 'Oh, that is spectacular!  I just love the change in the sky from ground up and the stars.  Congrats on your first ribbon and new personal best!', '2008-08-13 01:28:50.000000', NULL, 0),
(4884473, 707315, 62006, '<td valign="top">Very beautiful image. Well done and congrats on the blue.</td>', 'Very beautiful image. Well done and congrats on the blue.', '2008-08-13 01:31:28.000000', NULL, 0),
(4884476, 707473, 60862, '<td valign="top">Congrats, Joe!  Nothing like shots that come together at the last minute. :)</td>', 'Congrats, Joe!  Nothing like shots that come together at the last minute. :)', '2008-08-13 01:32:07.000000', NULL, 0),
(4884478, 705837, 60862, '<td valign="top">A nice, serene image.  Congrats on your honorable mention and new personal best score!</td>', 'A nice, serene image.  Congrats on your honorable mention and new personal best score!', '2008-08-13 01:32:40.000000', NULL, 0),
(4884480, 707315, 59267, '<td valign="top"><table align="center" width="95%"><tr><td><div class="textsm"><b>Originally posted by GUTomek:</b></div><hr/><i> I love Mt. Hood and you framed it beautifully.  From Timothy Lake?  I really like the light, the reflection and the clarity of all your details from close to far.  Would be very interested in knowing what you did to make this pop.  Congratulations! </i></td></tr></table> <br/>Yes, I believe it''s Timothy Lake, I found it through GPS on my route to Mt. Hood.</td>', 'Originally posted by GUTomek: I love Mt. Hood and you framed it beautifully.  From Timothy Lake?  I really like the light, the reflection and the clarity of all your details from close to far.  Would be very interested in knowing what you did to make this pop.  Congratulations!  Yes, I believe it''s Timothy Lake, I found it through GPS on my route to Mt. Hood.', '2008-08-13 01:32:56.000000', NULL, 0);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(4884493, 706734, 60862, '<td valign="top">Terrific perspective!  I want to climb into the image and walk into the distance. :)</td>', 'Terrific perspective!  I want to climb into the image and walk into the distance. :)', '2008-08-13 01:33:45.000000', NULL, 0),
(4884520, 706482, 83313, '<td valign="top">I promised you some feedback after the challenge. Here ''tis.<br/> <br/>I didn''t get around to voting this one. probably would have given it a 6, maybe a 5 if I was grumpy. I''m actually surprised to see that this did almost a dead 5. Good smooth tones in the sky and you caught a nice starburst view of the sun. My only real critique is the tip of the tree is barely cut off. I think perhaps it did so mediocre because it is so similar to stuff that everybody has seen lots of before. On the other hand, there are lots of high scoring images that copy previous winning shots. Damned if you do and damned if you don''t! Remember that a 5 on DPC is pretty good anywhere else. Your family will be showing this one off.<br/> <br/>You know what? I just realized that this is very similar in comp and features to my July freestudy entry, which scored even a bit less than yours. Maybe comparing the two will help identify some common traits that hurt both of them.<br/><a href="//www.dpchallenge.com/image.php?IMAGE_ID=704860" rel="nofollow" target="_blank"><img alt="'' . substr(''//images.dpchallenge.com/images_challenge/0-999/886/120/704860.jpg'', strrpos(''//images.dpchallenge.com/images_challenge/0-999/886/120/704860.jpg'', ''/'') + 1) . ''" border="0" src="//images.dpchallenge.com/images_challenge/0-999/886/120/704860.jpg"/></a></td>', 'I promised you some feedback after the challenge. Here ''tis. I didn''t get around to voting this one. probably would have given it a 6, maybe a 5 if I was grumpy. I''m actually surprised to see that this did almost a dead 5. Good smooth tones in the sky and you caught a nice starburst view of the sun. My only real critique is the tip of the tree is barely cut off. I think perhaps it did so mediocre because it is so similar to stuff that everybody has seen lots of before. On the other hand, there are lots of high scoring images that copy previous winning shots. Damned if you do and damned if you don''t! Remember that a 5 on DPC is pretty good anywhere else. Your family will be showing this one off. You know what? I just realized that this is very similar in comp and features to my July freestudy entry, which scored even a bit less than yours. Maybe comparing the two will help identify some common traits that hurt both of them.', '2008-08-13 01:39:57.000000', NULL, 0),
(4884523, 707350, 15711, '<td valign="top">Nice finish,mate. :~)</td>', 'Nice finish,mate. :~)', '2008-08-13 01:40:18.000000', NULL, 0),
